-- LOCAL ONLY. Monthly factual conference; HR27 informative HE; no salaries, money or external payroll.
BEGIN READ ONLY;SET LOCAL search_path=pg_catalog;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $installed$ DECLARE t text;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_calcular(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='2b027dfb87a1a34eaec3be37607563ae5b62031406522bb0b6d15e8714ba094d' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_calcular(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_guardar()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='a782033837e4fd49baa2217a5e9d597e8dcd91a2df0dbd56590c3f64bca0918a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_guardar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_historico_guardar()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='2d5319aa9a121cb8cf220a9468f8583f432c125262bc7310786f6e1384008175' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_historico_guardar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_trilho_final()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='f1f505b8aa19bf6236b287e1660cc4b35ffbe17c1d1624cfc04156f65b05d19a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_trilho_final()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.conferencia_reconciliar()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='082d8c4e6773900a13966cf75a2456c7c16c30ec432946db886a2ccf84145e38' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: folha_privado.conferencia_reconciliar()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_v3(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='67547f357fa27ec0673d5981f91a0ba5b8df159a4778b4718d3ce1ca7297574a' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_v3(text,jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b500968b4fd6734bc3f60f39efc6105c99e3b320cf52df7c600524149572a7cd' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'MONTHLY_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
FOREACH t IN ARRAY ARRAY['public.folha_conferencias_mensais','public.folha_conferencia_historico'] LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass(t) AND relowner='postgres'::regrole AND relrowsecurity) OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE c.oid=to_regclass(t) AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass(t) AND attnum>0 AND NOT attisdropped AND attacl IS NOT NULL AND attacl<>'{}'::aclitem[]) OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=to_regclass(t)) THEN RAISE EXCEPTION 'MONTHLY_RLS_ACL_DRIFT: %',t;END IF;
END LOOP;
IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.folha_conferencias_mensais'::regclass AND tgname='folha_conferencia_trilho_final' AND tgenabled='O' AND tgdeferrable AND tginitdeferred AND tgfoid='folha_privado.conferencia_trilho_final()'::regprocedure) OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgname IN('folha_conferencia_factos','folha_conferencia_ausencias','folha_conferencia_diaria','folha_conferencia_he','folha_conferencia_jornada','folha_conferencia_cadastro','folha_conferencia_calendario','folha_conferencia_guardar','folha_conferencia_historico_guardar') AND tgenabled<>'O') OR (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname LIKE 'folha_conferencia_%')<>10 THEN RAISE EXCEPTION 'MONTHLY_TRIGGER_DRIFT';END IF;
END $installed$;
DO $unused$ BEGIN IF EXISTS(SELECT 1 FROM public.folha_conferencias_mensais) OR EXISTS(SELECT 1 FROM public.folha_conferencia_historico) THEN RAISE EXCEPTION 'MONTHLY_USED_ROLLBACK_FORBIDDEN';END IF;END $unused$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_monthly_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x WHERE n.nspname='primeline_monthly_backup' AND x.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_monthly_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'MONTHLY_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_monthly_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'MONTHLY_DATA_DRIFT';END IF;END LOOP;END $data$;
SELECT 'MONTHLY_POSTCHECK_OK' resultado;COMMIT;
